def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and
               sum(row.count(grid[r][c]) for row in grid) == 1]
    if not markers:
        return out
    mr, mc, ink = markers[0]

    # Each contiguous edge segment projects a line through its midpoint.
    for side, vals in (
        ("left", [grid[r][0] for r in range(h)]),
        ("right", [grid[r][w-1] for r in range(h)]),
        ("top", grid[0]),
        ("bottom", grid[h-1]),
    ):
        i = 0
        while i < len(vals):
            if vals[i] == bg:
                i += 1
                continue
            j = i
            while j + 1 < len(vals) and vals[j+1] == vals[i]:
                j += 1
            mid = (i + j) // 2
            if side in ("left", "right"):
                for c in range(1, w-1):
                    out[mid][c] = ink
            else:
                for r in range(1, h-1):
                    out[r][mid] = ink
            i = j + 1

    # Project the isolated marker toward the nearest frame edge on its row/column.
    opts = []
    for dr, dc in ((0, -1), (0, 1), (-1, 0), (1, 0)):
        r, c = mr + dr, mc + dc
        while 0 <= r < h and 0 <= c < w and grid[r][c] == bg:
            r += dr
            c += dc
        if 0 <= r < h and 0 <= c < w:
            opts.append((abs(r-mr) + abs(c-mc), dr, dc))
    if opts:
        _, dr, dc = min(opts)
        out[mr][mc] = 4
        r, c = mr + dr, mc + dc
        while 0 <= r < h and 0 <= c < w and grid[r][c] == bg:
            out[r][c] = ink
            r += dr
            c += dc
    return out
